    private func submitFeedbackAndShowOffer() {
        guard let reason = feedbackReason else { return }

        Mixpanel.mainInstance().track(event: "Cancel Subscription Feedback", properties: [
            "reason": reason.rawValue,
            "additional_feedback": feedbackText,
            "subscription_type": currentTier.rawValue
        ])

        let hasReceivedTrial = UserDefaults.standard.bool(forKey: "hasReceivedCancellationTrial")

        if hasReceivedTrial {
            proceedWithCancellation()
        } else {
            withAnimation(.spring(response: 0.4)) {
                showFeedbackForm = false
                showTrialOffer = true
            }
        }
    }

    private func applyFreeTrial() {
        isApplyingTrial = true

        Mixpanel.mainInstance().track(event: "Free Trial Accepted", properties: [
            "source": "cancellation_flow",
            "subscription_type": currentTier.rawValue
        ])

        let currentExpiration = expirationDate ?? Date()
        let newExpiration = Calendar.current.date(byAdding: .month, value: 1, to: currentExpiration)

        UserDefaults.standard.set(newExpiration, forKey: "trialExtensionDate")
        UserDefaults.standard.set(true, forKey: "hasReceivedCancellationTrial")

        Mixpanel.mainInstance().people.set(properties: [
            "received_cancellation_trial": true,
            "trial_extension_date": newExpiration?.timeIntervalSince1970 ?? 0
        ])

        globalState.refreshAccessStatus()

        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
            isApplyingTrial = false
            withAnimation(.spring(response: 0.4)) {
                showTrialOffer = false
                trialApplied = true
            }
        }
    }

    private func proceedWithCancellation() {
        Mixpanel.mainInstance().track(event: "Free Trial Declined", properties: [
            "source": "cancellation_flow",
            "subscription_type": currentTier.rawValue
        ])

        if let url = URL(string: "https://apps.apple.com/account/subscriptions") {
            UIApplication.shared.open(url)
        }

        globalState.showCurrentSubscriptionView = false
        presentationMode.wrappedValue.dismiss()
    }
